  ("An image editor in the manner of the paint programs of 1994: layers, channels, Quick Mask, paths, artboards, type with Arabic, forty filters and the color adjustments.", "محرر صور على طريقة برامج الرسم في 1994: طبقات وقنوات وقناع سريع ومسارات وألواح رسم ونص بالعربية وأربعون مرشحًا وتعديلات الألوان."),
  ("Its engine is Retro Nim UI's own: retroui/photo, retroui/photopaint, retroui/photofx.", "محركه خاص بـ Retro Nim UI: retroui/photo وretroui/photopaint وretroui/photofx."),
  ("Not affiliated with any maker of image software.", "غير تابع لأي صانع لبرامج الصور."),
  ("Layers, type and filters -- as in 1994", "طبقات ونص ومرشحات -- كما في 1994"),
  ("32 Bits/Channel (HDR): Radiance .hdr and PFM files, 32-bit Preview, HDR Toning; PNG-24 and 32-bit BMP", "32 بت/قناة (HDR): ملفات Radiance ‏.hdr وPFM، ومعاينة 32 بت، وتدرج HDR؛ وPNG-24 وBMP بـ 32 بت"),
  ("Press-ready PDF: PDF/X-4, registration marks, color bars, page information, bleed; type kept as text (its font in the file)", "PDF جاهز للطباعة: PDF/X-4، علامات التسجيل، أشرطة الألوان، معلومات الصفحة، النزف؛ والنص يبقى نصًا (بخطه في الملف)"),
  ("Arabic: kashida where the scribes put it, the tashkeel kept on its letter; text in columns, flowing on into another box", "العربية: الكشيدة حيث يضعها الخطاطون، والتشكيل يبقى على حرفه؛ نص في أعمدة يتدفق إلى مربع آخر"),
  ("A new splash; Help > Report a Problem (a fault no longer closes the program)", "شاشة بداية جديدة؛ تعليمات > الإبلاغ عن مشكلة (لم يعد العطل يغلق البرنامج)"),
  ("The Filter Gallery: 30 filters (Artistic, Brush Strokes, Sketch, Texture); Oil Paint, Lighting Effects, Fibers, Displace, Smart Sharpen", "معرض المرشحات: 30 مرشحًا (فني، ضربات الفرشاة، رسم تخطيطي، نسيج)؛ الطلاء الزيتي، تأثيرات الإضاءة، ألياف، إزاحة، زيادة الحدة الذكية"),
  ("109 custom shapes in 12 sets; Live Shape size, corners, flips in Properties", "109 أشكال مخصصة في 12 مجموعة؛ حجم الشكل الحي وزواياه وقلبه في الخصائص"),
  ("The Slice, Note and Count tools; Slices to Files", "أدوات الشريحة والملاحظة والعد؛ الشرائح إلى ملفات"),
  ("The toolbar docked at the left, its header as the panels'; tabs as the panels' everywhere", "شريط الأدوات مثبت على اليسار، ورأسه كرؤوس اللوحات؛ وعلامات التبويب كعلامات اللوحات في كل مكان"),
  ("Faster: a 12-megapixel picture composites in half the time, opens and saves twice as fast", "أسرع: صورة 12 ميغابكسل تُركَّب في نصف الوقت، وتُفتح وتُحفظ أسرع بمرتين"),
  ("Documents as tabs in all the room between the toolbar and the panels; windows of their own (MDI) as an option (Window > Arrange)", "المستندات كعلامات تبويب في كل المساحة بين شريط الأدوات واللوحات؛ ونوافذ مستقلة (MDI) كخيار (نافذة > ترتيب)"),
  ("Panels docked as today's editors have them: tabs, groups, a column of icons, floating", "لوحات مثبتة كما في محررات اليوم: علامات تبويب ومجموعات وعمود أيقونات وتعويم"),
  ("A status bar under each picture: its zoom, size and what its menu says", "شريط حالة أسفل كل صورة: تكبيرها وحجمها وما تقوله قائمتها"),
  ("Adjustment Presets (36, and yours), Clarity, Dehaze and Grain", "الإعدادات المسبقة للتعديل (36، وإعداداتك)، الوضوح وإزالة الضباب والحبيبات"),
  ("Layer Cleanup, Harmonize, Colorize with color hints, Content-Aware expand", "تنظيف الطبقات، المواءمة، التلوين بتلميحات الألوان، التوسيع المدرك للمحتوى"),
  ("Artboards, the Frame tool, the Triangle, the Magnetic Lasso", "ألواح الرسم، أداة الإطار، المثلث، الحبل المغناطيسي"),
  ("Type: right-to-left and left-to-right, Arabic kashida, dynamic text", "النص: من اليمين لليسار ومن اليسار لليمين، الكشيدة العربية، النص الديناميكي"),
  ("Google Fonts fixed; Spot Healing and Patch as they work today", "إصلاح Google Fonts؛ المعالجة الموضعية والرقعة كما تعملان اليوم"),
  ("Icons: Nerd Fonts symbols (MIT / OFL) and Retro's own pixel icons.", "الأيقونات: رموز Nerd Fonts ‏(MIT / OFL) وأيقونات Retro النقطية الخاصة."),
