  ("Evens out skin -- blemishes, shine -- keeping its texture, the eyes and hair sharp.", "يوحّد البشرة -- العيوب واللمعان -- مع الحفاظ على نسيجها ووضوح العينين والشعر."),
  ("Smooths away the blocks and ringing of a photo saved too small.", "يزيل الكتل والحلقات من صورة حُفظت بحجم صغير جدًا."),
  ("Mends old photos: scratches and dust, grain, halftone dots, faded tones.", "يرمم الصور القديمة: الخدوش والغبار والحبيبات ونقاط نصف الدرجة والدرجات الباهتة."),
  ("Colors a black and white photo: click the picture to put the foreground color there -- each color runs out along what is alike and stops at edges. With no colors put: a warm old-photo tint.", "يلوّن صورة بالأبيض والأسود: انقر الصورة لوضع لون المقدمة هناك -- يمتد كل لون على امتداد ما يشبهه ويتوقف عند الحواف. وبلا ألوان: صبغة دافئة لصورة قديمة."),
  ("Blurs what is far, as a wide-open lens does: the subject is found, the ground is taken as nearer at the bottom, what is soft already as far.", "يموّه البعيد كما تفعل عدسة مفتوحة تمامًا: يُعثر على الموضوع، وتُعدّ الأرض أقرب في الأسفل، وما هو ناعم أصلًا بعيدًا."),
  ("Gives the picture the colors of another open document, or of a look.", "يمنح الصورة ألوان مستند مفتوح آخر، أو مظهرًا."),
  ("Matches the layer's colors and light to the layers under it, so it sits in the picture.", "يطابق ألوان الطبقة وإضاءتها مع الطبقات أسفلها، لتندمج في الصورة."),
  ("Makes the picture 2 to 4 times bigger, its edges kept sharp (opens as a new document).", "يكبّر الصورة من 2 إلى 4 أضعاف مع الحفاظ على حدة حوافها (تُفتح كمستند جديد)."),
