  ("Draw a box round a thing: the thing is selected.", "ارسم مربعًا حول شيء: يُحدد الشيء."),
  ("Zoom 1:1", "تكبير 1:1"),
  ("Drag the selection (or the whole layer) to move it; Shift keeps it straight. The arrow keys move it one pixel (Shift: ten).", "اسحب التحديد (أو الطبقة كلها) لنقله؛ Shift يبقيه مستقيمًا. مفاتيح الأسهم تنقله بكسلًا واحدًا (Shift: عشرة)."),
  ("Drag a box around what was photographed at an angle (a page, a sign, a building), then drag its four corners onto its edges: Enter makes it a rectangle. Esc cancels.", "اسحب مربعًا حول ما صُوّر بزاوية (صفحة، لافتة، مبنى)، ثم اسحب زواياه الأربع إلى حوافه: Enter يجعله مستطيلًا. Esc يلغي."),
  ("Drag along a line that should be level (a horizon) or upright: the image is turned and cut to what it fills.", "اسحب على امتداد خط يجب أن يكون مستويًا (الأفق) أو قائمًا: تُدوّر الصورة وتُقص إلى ما تملؤه."),
  ("Drag the part to keep; its handles change it (Shift: in proportion), dragging inside moves it. Click inside it or press Enter to crop, Esc to cancel.", "اسحب الجزء المراد الاحتفاظ به؛ مقابضه تغيّره (Shift: بالتناسب)، والسحب داخله ينقله. انقر داخله أو اضغط Enter للاقتصاص، Esc للإلغاء."),
  ("Contents:", "المحتويات:"),
  ("Angle: ", "الزاوية: "),
  ("The color under the cross in the brush's middle is rubbed out to transparency, and those like it: paint along an edge to lift a subject off its background.", "يُمسح اللون الواقع تحت الصليب في منتصف الفرشاة إلى الشفافية، وما يشبهه: اطلِ على امتداد حافة لفصل موضوع عن خلفيته."),
  ("Pressure", "الضغط"),
  ("Paints the foreground color over the color under the cross in the brush's middle (and those like it), keeping its light and shade: a red car made blue.", "يطلي لون المقدمة فوق اللون الواقع تحت الصليب في منتصف الفرشاة (وما يشبهه)، مع الحفاظ على ضوئه وظله: سيارة حمراء تصبح زرقاء."),
  ("Paints with the foreground color, mixing it with the paint already there (Wet: how much it picks up; Load: how long its paint lasts).", "يطلي بلون المقدمة ممزوجًا بالطلاء الموجود (الرطوبة: مقدار ما يلتقطه؛ التحميل: مدة بقاء طلائه)."),
  ("Paints back the image as it was: the state or snapshot marked with the brush in the History palette (Window > Palettes > History).", "يعيد رسم الصورة كما كانت: الحالة أو اللقطة المحددة بالفرشاة في لوحة السجل (نافذة > اللوحات > السجل)."),
  ("Option:", "الخيار:"),
  ("Clone (non-aligned)", "نسخ (غير محاذى)"),
  ("Pattern (non-aligned)", "نقش (غير محاذى)"),
  ("Source set: Alt+click for another", "تم تعيين المصدر: Alt+نقر لمصدر آخر"),
  ("Alt+click to set the source", "Alt+نقر لتعيين المصدر"),
  ("Paint over a spot or a small thing: it is made again from what is around it.", "اطلِ فوق بقعة أو شيء صغير: يُعاد تكوينه مما حوله."),
  ("Paint over what should go -- a person, a wire, a sign: it is taken away and what was behind it made up from round it. Paint a little past its edges.", "اطلِ فوق ما يجب إزالته -- شخص، سلك، لافتة: يُزال ويُكوَّن ما خلفه مما حوله. اطلِ قليلًا بعد حوافه."),
  ("Select something (or draw round it with this tool), then drag it elsewhere: it is fitted in there, and where it was is made up (Extend: copied, the original kept).", "حدد شيئًا (أو ارسم حوله بهذه الأداة)، ثم اسحبه إلى مكان آخر: يُدمج هناك، ويُعاد تكوين مكانه الأصلي (تمديد: يُنسخ ويُحتفظ بالأصل)."),
  ("Select what to mend (or draw round it with this tool), then drag it to the place whose texture it should take.", "حدد ما تريد إصلاحه (أو ارسم حوله بهذه الأداة)، ثم اسحبه إلى المكان الذي يجب أن يأخذ نسيجه."),
  ("Click a red pupil, or drag a box around the eye.", "انقر بؤبؤًا أحمر، أو اسحب مربعًا حول العين."),
  ("Curve Fit (px):", "ملاءمة المنحنى (px):"),
  ("Draw the path as with a pencil: it is made smooth curves when the mouse comes up (the higher the Curve Fit, the fewer its points). End where it began to close it.", "ارسم المسار كما بقلم رصاص: يصبح منحنيات ناعمة عند رفع الفأرة (كلما زادت ملاءمة المنحنى قلّت نقاطه). انتهِ حيث بدأت لإغلاقه."),
  ("Click points: the curve goes smoothly through them all. Drag a point to move it, Alt+click it for a corner; click the first point to close the shape.", "انقر نقاطًا: يمر المنحنى بها كلها بنعومة. اسحب نقطة لنقلها، Alt+نقر عليها لتصبح زاوية؛ انقر النقطة الأولى لإغلاق الشكل."),
  ("Click for corner points, drag for curves; click the first point to close the shape. The Paths palette fills, strokes or selects it.", "انقر لنقاط زوايا، واسحب للمنحنيات؛ انقر النقطة الأولى لإغلاق الشكل. لوحة المسارات تعبئه أو تحده أو تحدده."),
